import { createHash } from "node:crypto";
import * as fsPromises from "node:fs/promises";
import path from "node:path";
import type { AudioSourceResponse } from "../src/lib/types.js";

export function guessAudioMime(filePath: string): string {
  const lower = filePath.toLowerCase();
  if (lower.endsWith(".wav")) return "audio/wav";
  if (lower.endsWith(".m4a")) return "audio/mp4";
  if (lower.endsWith(".ogg")) return "audio/ogg";
  return "audio/mpeg";
}

export async function getAudioSource(filePath: string): Promise<AudioSourceResponse> {
  return {
    path: `local-audio:///${filePath.replaceAll("\\", "/")}`,
    mime: guessAudioMime(filePath),
  };
}


export async function computeContentId(filePath: string): Promise<string> {
  const stats = await fsPromises.stat(filePath);
  const hash = createHash("sha256");

  // 使用采样哈希而非全文件读取，提升大文件性能
  // 采样策略：文件头 64KB + 文件尾 64KB + 文件大小 + 修改时间
  const sampleSize = 64 * 1024; // 64KB

  if (stats.size <= sampleSize * 2) {
    // 小文件直接全量读取
    const data = await fsPromises.readFile(filePath);
    hash.update(data);
  } else {
    // 大文件采样读取
    const headBuffer = await readSampleRange(filePath, 0, sampleSize);
    const tailOffset = stats.size - sampleSize;
    const tailBuffer = await readSampleRange(filePath, tailOffset, sampleSize);

    hash.update(headBuffer);
    hash.update(tailBuffer);
  }

  // 加入文件大小和修改时间，确保唯一性
  hash.update(`:${stats.size}:${Math.floor(stats.mtimeMs)}`);

  return `sha256:${hash.digest("hex").toUpperCase()}`;
}

async function readSampleRange(filePath: string, start: number, length: number): Promise<Buffer> {
  const buffer = Buffer.alloc(length);
  const fd = await fsPromises.open(filePath, "r");
  try {
    const { buffer: readBuffer } = await fd.read(buffer, 0, length, start);
    return readBuffer;
  } finally {
    await fd.close();
  }
}

export function toRelativePath(rootPath: string, absolutePath: string) {
  return path.relative(rootPath, absolutePath).replaceAll("\\", "/");
}

import { spawn } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";
import type { WaveformResponse } from "../src/lib/types.js";

const WAVEFORM_CACHE_VERSION = 8;
const WAVEFORM_CACHE_ALGORITHM = "ffmpeg-f32le-peaks-v2";
const FFMPEG_SAMPLE_RATE = 16000;
const PROJECT_FFMPEG_PATH = path.resolve(import.meta.dirname, "../ffmpeg-8.1-essentials_build/bin/ffmpeg.exe");
const inflightWaveformJobs = new Map<string, Promise<WaveformResponse>>();
let ffmpegPathPromise: Promise<string> | null = null;

// 缓存清理配置
const MAX_CACHE_SIZE_MB = 500; // 最大缓存大小 500MB
const MAX_CACHE_FILES = 10000; // 最大缓存文件数

type WaveformCacheFile = WaveformResponse & { version: number; algorithm: string };

type WaveformJobInput = {
  contentId: string;
  filePath: string;
};

function getAppDataDir(getPath: (name: "appData") => string) {
  return path.join(getPath("appData"), "Soundbox");
}


function getWaveformDbDir(getPath: (name: "appData") => string) {
  return path.join(getAppDataDir(getPath), "waveform-db");
}

function getWaveformCachePath(getPath: (name: "appData") => string, contentId: string) {
  const sanitized = contentId.replaceAll(":", "_");
  const bucket = sanitized.slice(7, 9) || "00";
  return path.join(getWaveformDbDir(getPath), bucket, `${sanitized}.json`);
}

async function ensureWaveformDbDir(getPath: (name: "appData") => string, contentId: string) {
  await fs.mkdir(path.dirname(getWaveformCachePath(getPath, contentId)), { recursive: true });
}

async function resolveFfmpegPath() {
  if (!ffmpegPathPromise) {
    ffmpegPathPromise = (async () => {
      console.log("[ffmpeg] resolving path", PROJECT_FFMPEG_PATH);
      await fs.access(PROJECT_FFMPEG_PATH);
      console.log("[ffmpeg] path-ok", PROJECT_FFMPEG_PATH);
      return PROJECT_FFMPEG_PATH;
    })();
  }
  return ffmpegPathPromise;
}

async function readWaveformCacheSafe(
  getPath: (name: "appData") => string,
  contentId: string
): Promise<WaveformResponse | null> {
  const fallback: WaveformCacheFile = {
    version: WAVEFORM_CACHE_VERSION,
    algorithm: WAVEFORM_CACHE_ALGORITHM,
    duration: 0,
    peaks: [],
  };
  const cachePath = getWaveformCachePath(getPath, contentId);

  try {
    const raw = await fs.readFile(cachePath, "utf-8");
    const trimmed = raw.trim();
    if (!trimmed) {
      throw new SyntaxError("Waveform cache is empty");
    }

    const result = { ...fallback, ...(JSON.parse(trimmed) as Partial<WaveformCacheFile>) } as WaveformCacheFile;
    const peaks = Array.isArray(result.peaks)
      ? result.peaks.filter((value: unknown): value is number => typeof value === "number" && Number.isFinite(value))
      : [];

    if (result.version !== WAVEFORM_CACHE_VERSION || result.algorithm !== WAVEFORM_CACHE_ALGORITHM) {
      console.log("[waveform] cache-stale", {
        contentId,
        cachePath,
        version: result.version,
        algorithm: result.algorithm,
      });
      return null;
    }

    if (peaks.length === 0) {
      console.log("[waveform] cache-empty", { contentId, cachePath });
      return null;
    }

    return {
      duration: typeof result.duration === "number" && Number.isFinite(result.duration) ? result.duration : 0,
      peaks,
    };
  } catch (error) {
    console.warn("[waveform] cache-invalid, deleting", {
      contentId,
      cachePath,
      error: error instanceof Error ? error.message : String(error),
    });
    await fs.rm(cachePath, { force: true }).catch(() => undefined);
    await fs.rm(`${cachePath}.tmp`, { force: true }).catch(() => undefined);
    return null;
  }
}

async function writeWaveformCacheAtomic(
  getPath: (name: "appData") => string,
  contentId: string,
  waveform: WaveformResponse
) {
  await ensureWaveformDbDir(getPath, contentId);
  const payload: WaveformCacheFile = {
    version: WAVEFORM_CACHE_VERSION,
    algorithm: WAVEFORM_CACHE_ALGORITHM,
    ...waveform,
  };
  const targetPath = getWaveformCachePath(getPath, contentId);
  const tempPath = `${targetPath}.tmp`;
  await fs.writeFile(tempPath, JSON.stringify(payload, null, 2), "utf-8");
  await fs.rename(tempPath, targetPath);

  // 写入后检查并清理缓存
  await cleanupWaveformCache(getPath).catch((err) => {
    console.warn("[waveform] cache-cleanup-failed", err);
  });
}

// 缓存清理：LRU 策略 + 大小限制
async function cleanupWaveformCache(getPath: (name: "appData") => string) {
  const cacheDir = getWaveformDbDir(getPath);

  try {
    // 检查缓存目录是否存在
    try {
      await fs.access(cacheDir);
    } catch {
      return; // 目录不存在，无需清理
    }

    // 递归获取所有缓存文件
    const cacheFiles: Array<{ path: string; mtime: number; size: number }> = [];
    let totalSize = 0;

    async function scanDir(dirPath: string) {
      const entries = await fs.readdir(dirPath, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dirPath, entry.name);
        if (entry.isDirectory()) {
          await scanDir(fullPath);
        } else if (entry.name.endsWith(".json")) {
          const stats = await fs.stat(fullPath);
          cacheFiles.push({
            path: fullPath,
            mtime: stats.mtimeMs,
            size: stats.size,
          });
          totalSize += stats.size;
        }
      }
    }

    await scanDir(cacheDir);

    const totalSizeMB = totalSize / (1024 * 1024);
    console.log("[waveform] cache-stats", {
      totalFiles: cacheFiles.length,
      totalSizeMB: totalSizeMB.toFixed(2),
    });

    // 检查是否需要清理
    const needsCleanup = totalSizeMB > MAX_CACHE_SIZE_MB || cacheFiles.length > MAX_CACHE_FILES;
    if (!needsCleanup) {
      return;
    }

    console.log("[waveform] cache-cleanup-start", {
      reason: totalSizeMB > MAX_CACHE_SIZE_MB ? "size-exceeded" : "file-count-exceeded",
      currentSizeMB: totalSizeMB.toFixed(2),
      currentFiles: cacheFiles.length,
    });

    // 按修改时间排序（LRU：最久未使用的先删除）
    cacheFiles.sort((a, b) => a.mtime - b.mtime);

    // 删除旧文件直到满足限制
    let deletedCount = 0;
    let deletedSize = 0;

    for (const file of cacheFiles) {
      if (totalSizeMB <= MAX_CACHE_SIZE_MB && cacheFiles.length - deletedCount <= MAX_CACHE_FILES) {
        break;
      }

      try {
        await fs.rm(file.path, { force: true });
        deletedCount++;
        deletedSize += file.size;
      } catch (err) {
        console.warn("[waveform] cache-cleanup-delete-failed", { path: file.path, err });
      }
    }

    console.log("[waveform] cache-cleanup-complete", {
      deletedFiles: deletedCount,
      deletedSizeMB: (deletedSize / (1024 * 1024)).toFixed(2),
      remainingFiles: cacheFiles.length - deletedCount,
    });
  } catch (error) {
    console.error("[waveform] cache-cleanup-error", error);
    throw error;
  }
}

async function generateWaveformWithFfmpeg(filePath: string, sampleCount = 2048): Promise<WaveformResponse> {
  const ffmpegPath = await resolveFfmpegPath();
  const stats = await fs.stat(filePath);
  const args = [
    "-v",
    "error",
    "-i",
    filePath,
    "-ac",
    "1",
    "-ar",
    String(FFMPEG_SAMPLE_RATE),
    "-f",
    "f32le",
    "-acodec",
    "pcm_f32le",
    "pipe:1",
  ];

  const pcmBuffer = await new Promise<Buffer>((resolve, reject) => {
    const child = spawn(ffmpegPath, args, { windowsHide: true });
    const stdoutChunks: Buffer[] = [];
    const stderrChunks: Buffer[] = [];

    console.log("[ffmpeg] spawn", { filePath, ffmpegPath });
    child.stdout.on("data", (chunk: Buffer) => stdoutChunks.push(chunk));
    child.stderr.on("data", (chunk: Buffer) => stderrChunks.push(chunk));
    child.on("error", (error) => {
      console.error("[ffmpeg] spawn-error", { filePath, error });
      reject(error);
    });
    child.on("close", (code) => {
      console.log("[ffmpeg] close", {
        filePath,
        code,
        stdoutBytes: stdoutChunks.reduce((sum, chunk) => sum + chunk.length, 0),
        stderr: Buffer.concat(stderrChunks).toString("utf8"),
      });
      if (code === 0) {
        resolve(Buffer.concat(stdoutChunks));
        return;
      }
      reject(new Error(Buffer.concat(stderrChunks).toString("utf8") || `ffmpeg exited with code ${code}`));
    });
  });

  const sampleTotal = Math.floor(pcmBuffer.length / 4);
  console.log("[waveform] ffmpeg-output", { filePath, pcmBytes: pcmBuffer.length, sampleTotal });
  if (sampleTotal <= 0) {
    return {
      duration: 0,
      peaks: Array(sampleCount).fill(0),
    };
  }

  const samples = new Float32Array(pcmBuffer.buffer, pcmBuffer.byteOffset, sampleTotal);
  const duration = sampleTotal / FFMPEG_SAMPLE_RATE || Math.max(0, stats.size / 16000);
  const bucketSize = Math.max(1, Math.floor(sampleTotal / sampleCount));
  const peaks = new Array<number>(sampleCount).fill(0);

  for (let bucketIndex = 0; bucketIndex < sampleCount; bucketIndex++) {
    const start = bucketIndex * bucketSize;
    const end = bucketIndex === sampleCount - 1 ? sampleTotal : Math.min(sampleTotal, start + bucketSize);
    let maxPeak = 0;

    for (let sampleIndex = start; sampleIndex < end; sampleIndex++) {
      const value = Math.abs(samples[sampleIndex] ?? 0);
      if (value > maxPeak) maxPeak = value;
    }

    peaks[bucketIndex] = Math.min(1, maxPeak);
  }

  return { duration, peaks };
}

function createFallbackWaveform(): WaveformResponse {
  return {
    duration: 0,
    peaks: Array.from({ length: 1024 }, (_, index) => {
      const position = index / 1023;
      return Math.max(0.04, Math.sin(position * Math.PI) * 0.22);
    }),
  };
}

function getOrCreateWaveformJob(
  getPath: (name: "appData") => string,
  { contentId, filePath }: WaveformJobInput
): Promise<WaveformResponse> {
  const existing = inflightWaveformJobs.get(contentId);
  if (existing) {
    console.log("[waveform] in-flight-hit", { filePath, contentId });
    return existing;
  }

  const job = Promise.resolve().then(async () => {
    try {
      console.log("[waveform] generate-begin", { filePath, contentId });
      const waveform = await generateWaveformWithFfmpeg(filePath);
      console.log("[waveform] generated", {
        filePath,
        peaks: waveform.peaks.length,
        duration: waveform.duration,
        min: Math.min(...waveform.peaks),
        max: Math.max(...waveform.peaks),
        first: waveform.peaks.slice(0, 12),
      });
      await writeWaveformCacheAtomic(getPath, contentId, waveform);
      console.log("[waveform] generate-finish", { filePath, contentId });
      return waveform;
    } catch (error) {
      console.error("[waveform] generate-failed", { filePath, contentId, error });
      const fallbackWaveform = createFallbackWaveform();
      await writeWaveformCacheAtomic(getPath, contentId, fallbackWaveform).catch((cacheError) => {
        console.warn("[waveform] fallback-cache-write-failed", { filePath, contentId, cacheError });
      });
      return fallbackWaveform;
    } finally {

      inflightWaveformJobs.delete(contentId);
    }
  });

  inflightWaveformJobs.set(contentId, job);
  return job;
}

export async function getWaveformPeaks(
  getPath: (name: "appData") => string,
  computeContentId: (filePath: string) => Promise<string>,
  filePath: string
): Promise<WaveformResponse> {
  console.log("[waveform] request-begin", { filePath });
  const contentId = await computeContentId(filePath);
  console.log("[waveform] content-id-ready", { filePath, contentId });

  const cached = await readWaveformCacheSafe(getPath, contentId);
  console.log("[waveform] request", { filePath, contentId, hasCached: Boolean(cached) });

  if (cached) {
    console.log("[waveform] cache-hit", {
      filePath,
      peaks: cached.peaks.length,
      duration: cached.duration,
      min: Math.min(...cached.peaks),
      max: Math.max(...cached.peaks),
      first: cached.peaks.slice(0, 12),
    });
    return cached;
  }

  console.log("[waveform] cache-miss", { filePath, contentId });
  return getOrCreateWaveformJob(getPath, { contentId, filePath });
}

import path from "node:path";
import fs from "node:fs/promises";
import { createHash } from "node:crypto";
import { computeContentId, toRelativePath } from "./audio.js";
import type {
  AppSettings,
  AudioFile,
  ContentIndexEntry,
  ContentIndexFile,
  FileIndexEntry,
  FileIndexFile,
  FolderNode,
  LibraryConfig,
  LibrarySnapshot,
  LocalTagsFile,
  NameTagSuggestion,
} from "../src/lib/types.js";

const AUDIO_EXTENSIONS = new Set([".wav", ".mp3", ".m4a"]);
const DEFAULT_NAME_NORMALIZATION = {
  removableTokens: ["用烂了", "副本", "copy", "已剪"],
};

const DEFAULT_SETTINGS: AppSettings = {
  libraries: [],
  waveform_cache_path: null,
  tag_storage_mode: "local",
  custom_tag_path: null,
};

const DEFAULT_FILE_INDEX: FileIndexFile = {
  version: "2.0",
  libraries: {},
  files: [],
};

const DEFAULT_CONTENT_INDEX: ContentIndexFile = {
  version: "2.0",
  contents: {},
};

const DEFAULT_LOCAL_TAGS: LocalTagsFile = {
  version: "2.0",
  contents: {},
};

const DEFAULT_NAME_INDEX = {
  version: "1.0",
  names: {} as Record<string, { contentIds: string[]; tagHints: Record<string, string[]>; updatedAt: string }>,
};

export function createLibraryService(getAppDataDir: () => string) {
  function getLocalMetaDir() {
    return path.join(getAppDataDir(), "local-meta");
  }

  function getSettingsPath() {
    return path.join(getAppDataDir(), "settings.json");
  }

  function getFileIndexPath() {
    return path.join(getLocalMetaDir(), "file-index.json");
  }

  function getContentIndexPath() {
    return path.join(getLocalMetaDir(), "content-index.json");
  }

  function getLocalTagsPath() {
    return path.join(getLocalMetaDir(), "local-tags.json");
  }

  function getNameIndexPath() {
    return path.join(getLocalMetaDir(), "name-index.json");
  }

  function getNameNormalizationPath() {
    return path.join(getLocalMetaDir(), "name-normalization.json");
  }

  async function ensureAppDataDir() {
    await fs.mkdir(getAppDataDir(), { recursive: true });
  }

  async function ensureLocalMetaDir() {
    await fs.mkdir(getLocalMetaDir(), { recursive: true });
  }

  async function readJsonFile<T>(filePath: string, fallback: T): Promise<T> {
    try {
      const raw = await fs.readFile(filePath, "utf-8");
      const trimmed = raw.trim();
      if (!trimmed) {
        console.warn("[json] empty-file-fallback", { filePath });
        return fallback;
      }

      const parsed = JSON.parse(trimmed) as T;
      if (parsed && typeof parsed === "object" && fallback && typeof fallback === "object") {
        return { ...fallback, ...parsed } as T;
      }
      return parsed;
    } catch (error) {
      const errno = error as NodeJS.ErrnoException;
      if (errno.code === "ENOENT") {
        return fallback;
      }

      if (error instanceof SyntaxError) {
        console.warn("[json] parse-failed-fallback", {
          filePath,
          error: error.message,
        });
        return fallback;
      }

      throw error;
    }
  }

  async function loadSettingsFile(): Promise<AppSettings> {
    return readJsonFile(getSettingsPath(), DEFAULT_SETTINGS);
  }

  async function saveSettingsFile(settings: AppSettings) {
    await ensureAppDataDir();
    await fs.writeFile(getSettingsPath(), JSON.stringify(settings, null, 2), "utf-8");
  }

  async function readFileIndexFile(): Promise<FileIndexFile> {
    return readJsonFile(getFileIndexPath(), DEFAULT_FILE_INDEX);
  }

  async function writeFileIndexFile(fileIndex: FileIndexFile) {
    await ensureLocalMetaDir();
    await fs.writeFile(getFileIndexPath(), JSON.stringify(fileIndex, null, 2), "utf-8");
  }

  async function readContentIndexFile(): Promise<ContentIndexFile> {
    return readJsonFile(getContentIndexPath(), DEFAULT_CONTENT_INDEX);
  }

  async function writeContentIndexFile(contentIndex: ContentIndexFile) {
    await ensureLocalMetaDir();
    await fs.writeFile(getContentIndexPath(), JSON.stringify(contentIndex, null, 2), "utf-8");
  }

  async function readLocalTagsFile(): Promise<LocalTagsFile> {
    return readJsonFile(getLocalTagsPath(), DEFAULT_LOCAL_TAGS);
  }

  async function writeLocalTagsFile(localTags: LocalTagsFile) {
    await ensureLocalMetaDir();
    await fs.writeFile(getLocalTagsPath(), JSON.stringify(localTags, null, 2), "utf-8");
  }

  async function readNameIndexFile() {
    return readJsonFile(getNameIndexPath(), DEFAULT_NAME_INDEX);
  }

  async function writeNameIndexFile(nameIndex: typeof DEFAULT_NAME_INDEX) {
    await ensureLocalMetaDir();
    await fs.writeFile(getNameIndexPath(), JSON.stringify(nameIndex, null, 2), "utf-8");
  }

  async function readNameNormalizationConfig() {
    const config = await readJsonFile(getNameNormalizationPath(), DEFAULT_NAME_NORMALIZATION);
    await ensureLocalMetaDir();
    await fs.writeFile(getNameNormalizationPath(), JSON.stringify(config, null, 2), "utf-8");
    return config;
  }

  async function addLibrary(name: string, libraryPath: string, libType: string) {
    const settings = await loadSettingsFile();
    if (settings.libraries.some((library) => library.path === libraryPath)) {
      throw new Error("Library already exists");
    }

    const nextLibrary: LibraryConfig = {
      name,
      path: libraryPath,
      lib_type: libType,
    };

    await saveSettingsFile({
      ...settings,
      libraries: [...settings.libraries, nextLibrary],
    });
  }

  async function removeLibrary(libraryPath: string) {
    const settings = await loadSettingsFile();
    await saveSettingsFile({
      ...settings,
      libraries: settings.libraries.filter((library) => library.path !== libraryPath),
    });
  }

  function isAudioFile(filePath: string) {
    return AUDIO_EXTENSIONS.has(path.extname(filePath).toLowerCase());
  }

  function createLibraryId(libraryPath: string) {
    return `lib-${createHash("sha256").update(libraryPath).digest("hex").slice(0, 12)}`;
  }

  function normalizeAudioName(name: string, removableTokens: string[]) {
    return path
      .basename(name, path.extname(name))
      .toLowerCase()
      .replaceAll("（", "(")
      .replaceAll("）", ")")
      .replaceAll("[", " ")
      .replaceAll("]", " ")
      .replaceAll("(", " ")
      .replaceAll(")", " ")
      .replaceAll("_", " ")
      .split(/\s+/)
      .filter(Boolean)
      .filter((part) => !removableTokens.includes(part))
      .join(" ");
  }

  function buildTagHintsForName(contentIds: string[], localTags: LocalTagsFile) {
    const grouped: Record<string, string[]> = {};
    for (const contentId of contentIds) {
      const record = localTags.contents[contentId];
      if (!record) continue;
      for (const [group, entries] of Object.entries(record.tags)) {
        grouped[group] ??= [];
        for (const entry of entries) {
          if (!grouped[group].includes(entry.value)) {
            grouped[group].push(entry.value);
          }
        }
      }
    }
    return grouped;
  }

  function buildNameSuggestions(
    fileIndex: FileIndexFile,
    nameIndex: typeof DEFAULT_NAME_INDEX,
    localTags: LocalTagsFile,
    removableTokens: string[]
  ) {
    const suggestions: Record<string, NameTagSuggestion> = {};

    for (const file of fileIndex.files) {
      const hasContentTags = Boolean(localTags.contents[file.contentId]?.tags && Object.keys(localTags.contents[file.contentId].tags).length > 0);
      if (hasContentTags) continue;

      const normalizedName = normalizeAudioName(file.relativePath, removableTokens);
      const nameRecord = nameIndex.names[normalizedName];
      if (!nameRecord) continue;

      const tags = Object.entries(nameRecord.tagHints).flatMap(([group, values]) =>
        values.map((value) => ({ group, value }))
      );

      if (tags.length === 0) continue;
      const sourceCount = nameRecord.contentIds.length;
      suggestions[file.absolutePath] = {
        normalizedName,
        tags,
        sourceContentIds: nameRecord.contentIds,
        confidence: sourceCount >= 3 ? 0.95 : sourceCount === 2 ? 0.8 : 0.6,
        sourceSummary: `来自 ${sourceCount} 个同名内容的历史标签`,
      };
    }

    return suggestions;
  }

  async function buildDirectoryPreview(dirPath: string, rootPath: string): Promise<FolderNode> {
    const entries = await fs.readdir(dirPath, { withFileTypes: true });
    const children: FolderNode[] = [];
    const files: AudioFile[] = [];

    for (const entry of entries) {
      if (entry.name.startsWith(".")) continue;
      const entryPath = path.join(dirPath, entry.name);

      if (entry.isDirectory()) {
        children.push(await buildDirectoryPreview(entryPath, rootPath));
        continue;
      }

      if (!entry.isFile() || !isAudioFile(entryPath)) {
        continue;
      }

      const stats = await fs.stat(entryPath);
      files.push({
        name: entry.name,
        path: entryPath,
        extension: path.extname(entryPath).slice(1),
        size: stats.size,
        relativePath: toRelativePath(rootPath, entryPath),
      });
    }

    children.sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));
    files.sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));

    return {
      name: path.basename(dirPath) || "Root",
      path: dirPath,
      children,
      files,
    };
  }

  function buildTreeFromFileIndex(dirPath: string, entriesByDir: Map<string, FileIndexEntry[]>): FolderNode {
    const childDirs = [...entriesByDir.keys()]
      .filter((candidate) => candidate !== dirPath && path.dirname(candidate) === dirPath)
      .sort((a, b) => a.localeCompare(b, "zh-CN"));

    const files = (entriesByDir.get(dirPath) ?? []).map((entry) => ({
      name: path.basename(entry.absolutePath),
      path: entry.absolutePath,
      extension: entry.extension,
      size: entry.size,
      contentId: entry.contentId,
      relativePath: entry.relativePath,
    }));

    return {
      name: path.basename(dirPath) || "Root",
      path: dirPath,
      children: childDirs.map((childDir) => buildTreeFromFileIndex(childDir, entriesByDir)),
      files,
    };
  }

  async function scanDirectoryWithIndex(
    dirPath: string,
    rootPath: string,
    libraryId: string,
    libraryName: string,
    fileEntries: FileIndexEntry[],
    contentIndexEntries: ContentIndexFile["contents"]
  ): Promise<FolderNode> {
    const entries = await fs.readdir(dirPath, { withFileTypes: true });
    const children: FolderNode[] = [];
    const files: AudioFile[] = [];

    for (const entry of entries) {
      if (entry.name.startsWith(".")) continue;
      const entryPath = path.join(dirPath, entry.name);

      if (entry.isDirectory()) {
        children.push(
          await scanDirectoryWithIndex(entryPath, rootPath, libraryId, libraryName, fileEntries, contentIndexEntries)
        );
        continue;
      }

      if (!entry.isFile() || !isAudioFile(entryPath)) {
        continue;
      }

      const stats = await fs.stat(entryPath);
      const relativePath = toRelativePath(rootPath, entryPath);
      const contentId = await computeContentId(entryPath);
      const fileId = `${libraryId}:${relativePath}`;

      fileEntries.push({
        fileId,
        libraryId,
        libraryName,
        relativePath,
        absolutePath: entryPath,
        size: stats.size,
        modifiedAt: Math.floor(stats.mtimeMs / 1000),
        extension: path.extname(entryPath).slice(1),
        contentId,
      });

      const existingContent: ContentIndexEntry | undefined = contentIndexEntries[contentId];
      if (existingContent) {
        if (!existingContent.instances.includes(fileId)) {
          existingContent.instances.push(fileId);
        }
        if (!existingContent.canonicalName) {
          existingContent.canonicalName = entry.name;
        }
      } else {
        contentIndexEntries[contentId] = {
          canonicalName: entry.name,
          instances: [fileId],
        };
      }

      files.push({
        name: entry.name,
        path: entryPath,
        extension: path.extname(entryPath).slice(1),
        size: stats.size,
        contentId,
        relativePath,
      });
    }

    children.sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));
    files.sort((a, b) => a.name.localeCompare(b.name, "zh-CN"));

    return {
      name: path.basename(dirPath) || "Root",
      path: dirPath,
      children,
      files,
    };
  }

  async function listAudioFilesForSignature(dirPath: string, results: string[] = []): Promise<string[]> {
    const entries = await fs.readdir(dirPath, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.name.startsWith(".")) continue;
      const entryPath = path.join(dirPath, entry.name);

      if (entry.isDirectory()) {
        await listAudioFilesForSignature(entryPath, results);
        continue;
      }

      if (entry.isFile() && isAudioFile(entryPath)) {
        results.push(entryPath);
      }
    }

    return results;
  }

  async function computeLibrarySignature(libraryPath: string) {
    const files = await listAudioFilesForSignature(libraryPath);
    files.sort((a, b) => a.localeCompare(b, "zh-CN"));

    const hash = createHash("sha256");
    for (const filePath of files) {
      const stats = await fs.stat(filePath);
      hash.update(toRelativePath(libraryPath, filePath));
      hash.update(":");
      hash.update(String(stats.size));
      hash.update(":");
      hash.update(String(Math.floor(stats.mtimeMs)));
      hash.update("\n");
    }

    return {
      fileCount: files.length,
      signature: hash.digest("hex"),
    };
  }

  async function buildLibrarySnapshot(libraryPath: string): Promise<LibrarySnapshot> {
    const rootPath = path.resolve(libraryPath);
    const fileIndex = await readFileIndexFile();
    const contentIndex = await readContentIndexFile();
    const localTags = await readLocalTagsFile();
    const nameIndex = await readNameIndexFile();
    const normalizationConfig = await readNameNormalizationConfig();
    await ensureLocalMetaDir();

    const libraryId = createLibraryId(rootPath);
    const libraryEntries = fileIndex.files.filter((entry) => entry.libraryId === libraryId);
    const cachedLibraryPathMatches = fileIndex.libraries[libraryId]?.path === rootPath;
    const cachedSignature = createHash("sha256");
    const currentSignature = await computeLibrarySignature(rootPath);
    for (const entry of [...libraryEntries].sort((a, b) => a.relativePath.localeCompare(b.relativePath, "zh-CN"))) {
      cachedSignature.update(entry.relativePath);
      cachedSignature.update(":");
      cachedSignature.update(String(entry.size));
      cachedSignature.update(":");
      cachedSignature.update(String(Math.floor(entry.modifiedAt * 1000)));
      cachedSignature.update("\n");
    }
    const cacheLooksFresh =
      cachedLibraryPathMatches &&
      currentSignature.fileCount === libraryEntries.length &&
      currentSignature.signature === cachedSignature.digest("hex");


    if (cacheLooksFresh && libraryEntries.length > 0) {
      const entriesByDir = new Map<string, FileIndexEntry[]>();
      for (const entry of libraryEntries) {
        const dir = path.dirname(entry.absolutePath);
        const current = entriesByDir.get(dir) ?? [];
        current.push(entry);
        entriesByDir.set(dir, current);
      }

      return {
        tree: buildTreeFromFileIndex(rootPath, entriesByDir),
        fileIndex,
        contentIndex,
        localTags,
        nameIndex,
        nameSuggestions: buildNameSuggestions(fileIndex, nameIndex, localTags, normalizationConfig.removableTokens),
        usedCache: true,
        indexingComplete: true,
      };
    }

    return {
      tree: await buildDirectoryPreview(rootPath, rootPath),
      fileIndex,
      contentIndex,
      localTags,
      nameIndex,
      nameSuggestions: buildNameSuggestions(fileIndex, nameIndex, localTags, normalizationConfig.removableTokens),
      usedCache: false,
      indexingComplete: false,
    };
  }

  async function rebuildNameIndex(fileEntries: FileIndexEntry[], localTags: LocalTagsFile, libraryId: string) {
    const nameIndex = await readNameIndexFile();
    const normalizationConfig = await readNameNormalizationConfig();
    const currentFileIndex = await readFileIndexFile();
    const retainedLibraryFiles = currentFileIndex.files.filter((entry) => entry.libraryId !== libraryId);
    const nextFilesByContentId = new Map(fileEntries.map((file) => [file.contentId, file]));

    for (const [normalizedName, record] of Object.entries(nameIndex.names)) {
      const retainedContentIds = record.contentIds.filter((contentId) => {
        if (nextFilesByContentId.has(contentId)) {
          return true;
        }
        return retainedLibraryFiles.some((entry) => {
          return entry.contentId === contentId && normalizeAudioName(entry.relativePath, normalizationConfig.removableTokens) === normalizedName;
        });
      });

      if (retainedContentIds.length === 0) {
        delete nameIndex.names[normalizedName];
        continue;
      }

      nameIndex.names[normalizedName] = {
        ...record,
        contentIds: retainedContentIds,
        tagHints: buildTagHintsForName(retainedContentIds, localTags),
        updatedAt: new Date().toISOString(),
      };
    }

    for (const file of fileEntries) {
      const normalizedName = normalizeAudioName(file.relativePath, normalizationConfig.removableTokens);
      const record = nameIndex.names[normalizedName] ?? {
        contentIds: [],
        tagHints: {},
        updatedAt: new Date().toISOString(),
      };

      if (!record.contentIds.includes(file.contentId)) {
        record.contentIds.push(file.contentId);
      }

      record.tagHints = buildTagHintsForName(record.contentIds, localTags);
      record.updatedAt = new Date().toISOString();
      nameIndex.names[normalizedName] = record;
    }

    await writeNameIndexFile(nameIndex);
    return { nameIndex, normalizationConfig };
  }


  async function buildLibraryIndex(libraryPath: string): Promise<LibrarySnapshot> {
    const rootPath = path.resolve(libraryPath);
    const libraryId = createLibraryId(rootPath);
    const libraryName = path.basename(rootPath) || "Root";
    const localTags = await readLocalTagsFile();
    const currentFileIndex = await readFileIndexFile();
    const currentContentIndex = await readContentIndexFile();

    const nextFileEntries: FileIndexEntry[] = [];
    const nextContentEntries: ContentIndexFile["contents"] = {};
    const tree = await scanDirectoryWithIndex(rootPath, rootPath, libraryId, libraryName, nextFileEntries, nextContentEntries);

    const mergedFileIndex: FileIndexFile = {
      ...currentFileIndex,
      libraries: {
        ...currentFileIndex.libraries,
        [libraryId]: {
          name: libraryName,
          path: rootPath,
        },
      },
      files: [...currentFileIndex.files.filter((entry) => entry.libraryId !== libraryId), ...nextFileEntries],
    };

    const currentLibraryFileIds = new Set(
      currentFileIndex.files.filter((entry) => entry.libraryId === libraryId).map((entry) => entry.fileId)
    );
    const retainedContentEntries = Object.fromEntries(
      Object.entries(currentContentIndex.contents)
        .map(([contentId, entry]) => {
          const remainingInstances = entry.instances.filter((fileId) => !currentLibraryFileIds.has(fileId));
          if (remainingInstances.length === 0) {
            return null;
          }
          return [contentId, { ...entry, instances: remainingInstances }] as const;
        })
        .filter((entry): entry is readonly [string, ContentIndexEntry] => Boolean(entry))
    );

    const mergedContentIndex: ContentIndexFile = {
      ...currentContentIndex,
      contents: {
        ...retainedContentEntries,
        ...nextContentEntries,
      },
    };


    await writeFileIndexFile(mergedFileIndex);
    await writeContentIndexFile(mergedContentIndex);

    const { nameIndex, normalizationConfig } = await rebuildNameIndex(nextFileEntries, localTags, libraryId);


    return {
      tree,
      fileIndex: mergedFileIndex,
      contentIndex: mergedContentIndex,
      localTags,
      nameIndex,
      nameSuggestions: buildNameSuggestions(mergedFileIndex, nameIndex, localTags, normalizationConfig.removableTokens),
      usedCache: false,
      indexingComplete: true,
    };
  }

  return {
    getLocalMetaDir,
    loadSettingsFile,
    saveSettingsFile,
    readFileIndexFile,
    readContentIndexFile,
    readLocalTagsFile,
    addLibrary,
    removeLibrary,
    buildLibrarySnapshot,
    buildLibraryIndex,
    writeLocalTagsFile,
  };
}

import { app, BrowserWindow, ipcMain, protocol } from "electron";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { computeContentId, getAudioSource } from "./audio.js";
import { getWaveformPeaks as getWaveformPeaksForFile } from "./ffmpeg.js";
import { selectFolder } from "./system.js";
import { createLibraryService } from "./library.js";
import { createTagService } from "./tags.js";
import { createDragDebugStore, registerDragOutHandler, registerLocalAudioProtocol } from "./protocols.js";
import type { AppSettings } from "../src/lib/types.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DEV_SERVER_URL = process.env.VITE_DEV_SERVER_URL;

function getAppDataDir() {
  return path.join(app.getPath("appData"), "Soundbox");
}


async function getSyncStatus() {
  return {
    mode: "local-only",
    localMetaPath: path.join(getAppDataDir(), "local-meta"),
    sharedMetaPath: null,
    lastSyncAt: null,
    pendingChanges: 0,
  };
}

const libraryService = createLibraryService(getAppDataDir);
const tagService = createTagService({
  readLocalTagsFile: libraryService.readLocalTagsFile,
  writeLocalTagsFile: libraryService.writeLocalTagsFile,
});
const dragDebugStore = createDragDebugStore();

function registerIpcHandlers() {
  ipcMain.handle("soundbox:select-folder", () => selectFolder());
  ipcMain.handle("soundbox:load-settings", () => libraryService.loadSettingsFile());
  ipcMain.handle("soundbox:save-settings", (_event, settings: AppSettings) => libraryService.saveSettingsFile(settings));
  ipcMain.handle("soundbox:add-library", (_event, name: string, libraryPath: string, libType: string) =>
    libraryService.addLibrary(name, libraryPath, libType)
  );
  ipcMain.handle("soundbox:remove-library", (_event, libraryPath: string) => libraryService.removeLibrary(libraryPath));
  ipcMain.handle("soundbox:get-audio-source", (_event, filePath: string) => getAudioSource(filePath));
  ipcMain.handle("soundbox:get-sync-status", () => getSyncStatus());
  ipcMain.handle("soundbox:read-file-index", () => libraryService.readFileIndexFile());
  ipcMain.handle("soundbox:read-content-index", () => libraryService.readContentIndexFile());
  ipcMain.handle("soundbox:read-local-tags", () => libraryService.readLocalTagsFile());
  ipcMain.handle("soundbox:build-library-snapshot", (_event, libraryPath: string) => libraryService.buildLibrarySnapshot(libraryPath));
  ipcMain.handle("soundbox:build-library-index", (_event, libraryPath: string) => libraryService.buildLibraryIndex(libraryPath));
  ipcMain.handle("soundbox:add-tag", (_event, contentId: string, group: string, value: string, author: string) =>
    tagService.addTag(contentId, group, value, author)
  );
  ipcMain.handle("soundbox:remove-tag", (_event, contentId: string, group: string, value: string) =>
    tagService.removeTag(contentId, group, value)
  );
  ipcMain.handle("soundbox:get-waveform-peaks", (_event, filePath: string) =>
    getWaveformPeaksForFile((name) => app.getPath(name), computeContentId, filePath)
  );
  ipcMain.handle("soundbox:get-drag-debug-state", () => dragDebugStore.getDragDebugState());
  registerDragOutHandler(ipcMain, dragDebugStore);
}

function createMainWindow() {
  console.log("[main] create-window:start");
  const window = new BrowserWindow({
    width: 1200,
    height: 800,
    minWidth: 900,
    minHeight: 600,
    title: "Soundbox",

    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });

  window.webContents.on("did-start-loading", () => console.log("[main] window:did-start-loading"));
  window.webContents.on("did-finish-load", () => console.log("[main] window:did-finish-load"));
  window.webContents.on("did-fail-load", (_event, code, description) => {
    console.error("[main] window:did-fail-load", { code, description });
  });
  window.webContents.on("render-process-gone", (_event, details) => {
    console.error("[main] window:render-process-gone", details);
  });

  if (DEV_SERVER_URL) {
    console.log("[main] load-url", DEV_SERVER_URL);
    void window.loadURL(DEV_SERVER_URL);
    window.webContents.openDevTools({ mode: "detach" });
    return;
  }

  const distPath = path.join(__dirname, "../dist/index.html");
  console.log("[main] load-file", distPath);
  void window.loadFile(distPath);
}

app.whenReady().then(() => {
  console.log("[main] app:ready");
  registerLocalAudioProtocol(protocol);
  registerIpcHandlers();
  createMainWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createMainWindow();
    }
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

import { contextBridge, ipcRenderer } from "electron";
import type { AppSettings, DragDebugState } from "../src/lib/types.js";



const notImplemented = (name: string) => async () => {
  throw new Error(`Electron 最小宿主壳尚未实现 ${name}`);
};

/**
 * 拖出文件到外部应用（如 Premiere、桌面、文件夹）
 * 按照 Video Hub App 模式：只发送，不等待返回
 * @param filePath 要拖出的文件路径
 * @param iconPath 可选的图标路径（将作为拖拽时显示的图标）
 */
function dragOutFile(filePath: string, iconPath?: string): void {
  ipcRenderer.send("soundbox:drag-out-file", filePath, iconPath);
}



const soundbox = {
  platform: process.platform,
  selectFolder: () => ipcRenderer.invoke("soundbox:select-folder"),
  scanDirectory: notImplemented("scanDirectory"),
  buildLibrarySnapshot: (path: string) => ipcRenderer.invoke("soundbox:build-library-snapshot", path),
  buildLibraryIndex: (path: string) => ipcRenderer.invoke("soundbox:build-library-index", path),
  readFileIndex: () => ipcRenderer.invoke("soundbox:read-file-index"),
  readContentIndex: () => ipcRenderer.invoke("soundbox:read-content-index"),
  readLocalTags: () => ipcRenderer.invoke("soundbox:read-local-tags"),
  addTag: (contentId: string, group: string, value: string, author = "user") =>
    ipcRenderer.invoke("soundbox:add-tag", contentId, group, value, author),
  removeTag: (contentId: string, group: string, value: string) =>
    ipcRenderer.invoke("soundbox:remove-tag", contentId, group, value),
  loadSettings: () => ipcRenderer.invoke("soundbox:load-settings"),
  saveSettings: (settings: AppSettings) => ipcRenderer.invoke("soundbox:save-settings", settings),
  addLibrary: (name: string, path: string, libType: string) => ipcRenderer.invoke("soundbox:add-library", name, path, libType),
  removeLibrary: (path: string) => ipcRenderer.invoke("soundbox:remove-library", path),
  getAudioSource: (path: string) => ipcRenderer.invoke("soundbox:get-audio-source", path),
  getWaveformPeaks: (path: string) => ipcRenderer.invoke("soundbox:get-waveform-peaks", path),
  getSyncStatus: () => ipcRenderer.invoke("soundbox:get-sync-status"),
  getDragDebugState: (): Promise<DragDebugState> => ipcRenderer.invoke("soundbox:get-drag-debug-state"),
  dragOutFile,
};


contextBridge.exposeInMainWorld("soundbox", soundbox);

import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { SettingsDialog } from "@/components/SettingsDialog";
