import { useLibraryDomain } from "@/hooks/useLibraryDomain";
import { usePlayerDomain } from "@/hooks/usePlayerDomain";
import { useTagDomain } from "@/hooks/useTagDomain";
import { Music, Settings, PanelLeft } from "lucide-react";
import { getDragDebugState, getWaveformPeaks } from "./lib/api";
import { getDragStateSummary } from "./lib/drag-state";
import { mergeMiniWaveforms } from "./lib/app-effects";
import { buildAppShellViewModel } from "./lib/use-app-shell-view";
import { shouldApplyMiniWaveformBatch } from "./lib/use-mini-waveforms";
import { buildDragDebugSummary, createDragDebugPoller } from "./lib/use-drag-debug";
