const TAG_GROUPS = [
  { key: "mood", label: "情绪", options: ["激昂", "悲伤", "悬疑", "温馨", "紧张", "轻松", "浪漫", "恐怖"] },
  { key: "energy", label: "能量", options: ["高", "中", "低"] },
  { key: "type", label: "类型", options: ["BGM", "音效", "环境音", "人声"] },
  { key: "source", label: "来源", options: [] },
  { key: "custom", label: "自定义", options: [] },
];

const LIBRARY_TYPES = [
  { value: "music", label: "音乐" },
  { value: "sfx", label: "音效" },
  { value: "ambient", label: "环境音" },
  { value: "voice", label: "人声" },
];

function App() {
  const [dragDebugState, setDragDebugState] = useState<DragDebugState | null>(null);
  const miniWaveformJobIdRef = useRef(0);

  const ui = useAppUiState();
  const player = usePlayerDomain();
  const library = useLibraryDomain({
    createInitialPlayerState,
    resetPlayerState: player.resetPlayerState,
    clearAudioElement: player.clearAudioElement,
  });
  const tags = useTagDomain({
    activeLibrary: library.activeLibrary,
    currentFile: player.currentFile,
    allFiles: library.allFiles,
    tags: library.tags,
    nameSuggestions: library.nameSuggestions,
    contentIndex: library.contentIndex,
    miniWaveforms: library.miniWaveforms,
    applySnapshot: library.applySnapshot,
    cacheSnapshot: library.cacheSnapshot,
  });

  useEffect(() => {
    return createDragDebugPoller(getDragDebugState, setDragDebugState);
  }, []);

  const { filteredFiles, allUniqueTags, currentTagInspectorMeta } = useMemo(() => {
    return buildAppShellViewModel({
      folderTree: library.folderTree,
      selectedFolderPath: library.selectedFolderPath,
      contentIndex: library.contentIndex,
      tags: library.tags,
      nameSuggestions: library.nameSuggestions,
      searchQuery: ui.searchQuery,
      tagFilters: tags.tagFilters,
      currentFilePath: player.currentFile?.path ?? null,
      allFiles: library.allFiles,
    });
  }, [
    library.folderTree,
    library.selectedFolderPath,
    library.contentIndex,
    library.tags,
    library.nameSuggestions,
    ui.searchQuery,
    tags.tagFilters,
    player.currentFile,
    library.allFiles,
  ]);

  useEffect(() => {
    if (filteredFiles.length === 0) {
      return;
    }

    const missingFiles = filteredFiles.filter((file) => !library.miniWaveforms[file.path]?.length).slice(0, 60);
    if (missingFiles.length === 0) return;

    const jobId = ++miniWaveformJobIdRef.current;

    Promise.all(
      missingFiles.map(async (file) => {
        try {
          const waveform = await getWaveformPeaks(file.path);
          return [file.path, waveform.peaks] as const;
        } catch (error) {
          console.error("Mini waveform load failed:", file.path, error);
          return null;
        }
      })
    ).then((results) => {
      if (!shouldApplyMiniWaveformBatch(jobId, miniWaveformJobIdRef.current)) return;
      const entries = results.filter((result): result is readonly [string, number[]] => Boolean(result));
      if (entries.length === 0) return;
      library.setMiniWaveforms((prev) => mergeMiniWaveforms(prev, entries));
    });
  }, [filteredFiles, library.miniWaveforms, library.setMiniWaveforms]);

  const handleSelectFile = (name: string, path: string) => {
    const nextSelection = player.selectFile(name, path);
    if (nextSelection.hideTagEditor) {
      tags.setShowTagEditor(false);
    }
  };

  return (
    <div className="flex h-screen flex-col bg-background text-foreground select-none">
      <audio ref={player.audioRef} preload="metadata" />

      <header className="flex h-10 items-center border-b px-4 text-sm font-medium">
        <Music className="mr-2 h-4 w-4" />
        <span>Soundbox</span>
        <div className="ml-auto flex items-center gap-2">
          {dragDebugState && (
            <div className="rounded border px-2 py-1 text-[10px] text-muted-foreground max-w-[360px] truncate">
              drag: {buildDragDebugSummary(dragDebugState)?.stage ?? dragDebugState.stage} · {getDragStateSummary(dragDebugState)}
            </div>
          )}
          <Button variant="ghost" size="sm" onClick={() => ui.setShowSidebar(!ui.showSidebar)}><PanelLeft className="h-4 w-4" /></Button>
          <Button variant="ghost" size="sm" onClick={() => ui.setShowDropInspector((prev) => !prev)}>拖放观察</Button>
          <Button variant="ghost" size="sm" onClick={() => ui.setShowSettings(true)}><Settings className="h-4 w-4" /></Button>
          <span className="text-xs text-muted-foreground">v1.0.0</span>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        <LibrarySidebar
          visible={ui.showSidebar}
          width={ui.sidebarWidth}
          libraries={library.libraries}
          activeLibrary={library.activeLibrary}
          allUniqueTags={allUniqueTags}
          tagFilters={tags.tagFilters}
          folderTree={library.folderTree}
          selectedFolderPath={library.selectedFolderPath}
          expandedFolders={library.expandedFolders}
          libraryLoadState={library.libraryLoadState}
          onSelectLibrary={library.selectLibrary}
          onToggleTagFilter={tags.toggleTagFilter}
          onClearTagFilters={() => tags.setTagFilters(new Set())}
          onToggleFolder={library.toggleFolder}
          onSelectFolder={library.setSelectedFolderPath}
          onStartResize={() => ui.setIsResizingSidebar(true)}
        />

        <div className="flex flex-1 flex-col overflow-hidden">
          <FileListPanel
            searchQuery={ui.searchQuery}
            filteredFiles={filteredFiles}
            currentFilePath={player.currentFile?.path ?? null}
            librariesCount={library.libraries.length}
            libraryLoadStateStatus={library.libraryLoadState.status}
            contentIndex={library.contentIndex}
            tags={library.tags}
            nameSuggestions={library.nameSuggestions}
            miniWaveforms={library.miniWaveforms}
            currentTime={player.currentTime}
            duration={player.duration}
            onSearchChange={ui.setSearchQuery}
            onSelectFile={handleSelectFile}
          />

          <WaveformPlayer
            currentFile={player.currentFile}
            isLoading={player.isLoading}
            currentTime={player.currentTime}
            duration={player.duration}
            isPlaying={player.isPlaying}
            isMuted={player.isMuted}
            volume={player.volume}
            progressRef={player.progressRef}
