// Memoized MiniWaveform component
const MiniWaveform = memo(function MiniWaveform({
  peaks,
  active,
  progress,
}: {
  peaks?: number[];
  active: boolean;
  progress: number | null;
}) {
  const canvasRef = useCallback((canvas: HTMLCanvasElement | null) => {
    if (!canvas || !peaks?.length) return;

    const wrapper = canvas.parentElement;
    if (!wrapper) return;

    const dpr = window.devicePixelRatio || 1;
    const cssWidth = wrapper.clientWidth || 200;
    const cssHeight = wrapper.clientHeight || 48;

    canvas.width = Math.floor(cssWidth * dpr);
    canvas.height = Math.floor(cssHeight * dpr);
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.scale(dpr, dpr);

    const width = cssWidth;
    const height = cssHeight;
    const mid = height / 2;
    const background = active ? "rgba(99,102,241,0.10)" : "rgba(100,116,139,0.10)";
    const stroke = active ? "#6366f1" : "rgba(51,65,85,0.82)";
    const sampleStep = peaks.length / width;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    ctx.beginPath();

    for (let x = 0; x < width; x++) {
      const start = Math.floor(x * sampleStep);
      const end = x === width - 1 ? peaks.length : Math.max(start + 1, Math.floor((x + 1) * sampleStep));
      let max = 0;
      for (let index = start; index < end; index++) {
        max = Math.max(max, peaks[index] ?? 0);
      }
      const visiblePeak = max > 0 ? Math.max(max, 0.02) : 0;
      ctx.moveTo(x + 0.5, mid - visiblePeak * mid * 0.88);
      ctx.lineTo(x + 0.5, mid + visiblePeak * mid * 0.88);
    }

    ctx.stroke();

    if (progress !== null) {
      const clamped = Math.min(1, Math.max(0, progress));
      const cursorX = clamped * width;
      ctx.strokeStyle = "#ef4444";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(cursorX + 0.5, 0);
      ctx.lineTo(cursorX + 0.5, height);
      ctx.stroke();
    }
  }, [peaks, active, progress]);

  if (!peaks?.length) {
    return <div className="h-12 rounded-md border border-dashed bg-muted/30" />;
  }

  return (
    <div
      className={`h-12 w-full rounded-md border overflow-hidden ${
        active ? "bg-primary/5 border-primary/30" : "bg-muted/30 border-border"
      }`}
    >
      <canvas ref={canvasRef} className="block h-full w-full" />
    </div>
  );
});

