export type LibraryDomainState = {
  libraries: LibraryConfig[];
  activeLibrary: string;
  folderTree: FolderNode[];
  selectedFolderPath: string | null;
  expandedFolders: Set<string>;
  allFiles: FileMeta[];
  tags: Record<string, TagEntry[]>;
  nameSuggestions: Record<string, NameTagSuggestion>;
  miniWaveforms: MiniWaveformMap;
  contentIndex: ContentIndexFile | null;
  syncStatus: SyncStatus | null;
  libraryLoadState: LibraryLoadState;
};

export function useLibraryDomain(options: {
  createInitialPlayerState: () => PlayerState;
  resetPlayerState: (playerState: PlayerState) => void;
  clearAudioElement: () => void;
}) {
  const { createInitialPlayerState: makeInitialPlayerState, resetPlayerState, clearAudioElement } = options;

  const [state, setState] = useState<LibraryDomainState>({
    libraries: [],
    activeLibrary: "",
    folderTree: [],
    selectedFolderPath: null,
    expandedFolders: new Set(),
    allFiles: [],
    tags: {},
    nameSuggestions: {},
    miniWaveforms: {},
    contentIndex: null,
    syncStatus: null,
    libraryLoadState: { status: "idle" },
  });
  const [newLibName, setNewLibName] = useState("");
  const [newLibType, setNewLibType] = useState("music");

  const libraryCacheRef = useRef(new Map<string, Awaited<ReturnType<typeof buildLibrarySnapshot>>>());
  const libraryRequestIdRef = useRef(0);
  const miniWaveformsRef = useRef<MiniWaveformMap>({});
  const selectedFolderPathRef = useRef<string | null>(null);

  useEffect(() => {
    miniWaveformsRef.current = state.miniWaveforms;
  }, [state.miniWaveforms]);

  useEffect(() => {
    selectedFolderPathRef.current = state.selectedFolderPath;
  }, [state.selectedFolderPath]);

  const applySnapshot = useCallback((snapshot: Awaited<ReturnType<typeof buildLibrarySnapshot>>) => {
    const derived = buildSnapshotState(snapshot, miniWaveformsRef.current, selectedFolderPathRef.current);
    setState((prev) => ({
      ...prev,
      folderTree: derived.folderTree,
      expandedFolders: derived.expandedFolders,
      selectedFolderPath: derived.selectedFolderPath,
      contentIndex: derived.contentIndex,
      tags: derived.tags,
      nameSuggestions: derived.nameSuggestions,
      allFiles: derived.allFiles,
      miniWaveforms: derived.miniWaveforms,
      libraryLoadState: derived.libraryLoadState,
    }));
  }, []);

  const clearLibraryView = useCallback(() => {
    const clearedState = buildLibraryClearedState();
    setState((prev) => ({
      ...prev,
      folderTree: clearedState.folderTree,
      expandedFolders: clearedState.expandedFolders,
      selectedFolderPath: clearedState.selectedFolderPath,
      allFiles: clearedState.allFiles,
      tags: clearedState.tags,
      nameSuggestions: clearedState.nameSuggestions,
      miniWaveforms: clearedState.miniWaveforms,
      contentIndex: clearedState.contentIndex,
    }));
    resetPlayerState(makeInitialPlayerState());
    clearAudioElement();
  }, [clearAudioElement, makeInitialPlayerState, resetPlayerState]);

  const refreshActiveLibrarySnapshot = useCallback(async () => {
    if (!state.activeLibrary) return;
    const snapshot = await buildLibrarySnapshot(state.activeLibrary);
    libraryCacheRef.current.set(state.activeLibrary, snapshot);
    applySnapshot(snapshot);
  }, [applySnapshot, state.activeLibrary]);

  const selectLibrary = useCallback(async (path: string) => {
    const requestId = ++libraryRequestIdRef.current;
    setState((prev) => ({ ...prev, activeLibrary: path }));

    const shouldApplyResult = (targetPath: string) => {
      return shouldApplyLibraryResult(requestId, libraryRequestIdRef.current, targetPath, path);
    };

    const cached = libraryCacheRef.current.get(path);
    if (cached) {
      if (shouldApplyResult(path)) {
        applySnapshot(cached);
      }
      return;
    }

    setState((prev) => ({
      ...prev,
      libraryLoadState: buildLibraryLoadingState("正在读取目录结构..."),
    }));

    try {
      const previewSnapshot = await buildLibrarySnapshot(path);
      if (!shouldApplyResult(path)) return;
      applySnapshot(previewSnapshot);

      if (shouldTriggerBackgroundIndex(previewSnapshot)) {
        void scheduleBackgroundIndex({
          snapshot: previewSnapshot,
          libraryPath: path,
          runBuildLibraryIndex: buildLibraryIndex,
          shouldApplyResult,
          onCompleted: (fullSnapshot) => {
            libraryCacheRef.current.set(path, fullSnapshot);
            applySnapshot(fullSnapshot);
          },
          onError: (indexErr) => {
            console.error("Background indexing failed:", indexErr);
            setState((prev) => ({
              ...prev,
              libraryLoadState: createLibraryLoadErrorState(indexErr),
            }));
          },
        });
      } else {
        libraryCacheRef.current.set(path, previewSnapshot);
      }
    } catch (err) {
      if (!shouldApplyResult(path)) return;
      const errorResult = buildLibraryErrorResult(err);
      setState((prev) => ({
        ...prev,
        folderTree: errorResult.clearedState.folderTree,
        expandedFolders: errorResult.clearedState.expandedFolders,
        selectedFolderPath: errorResult.clearedState.selectedFolderPath,
        allFiles: errorResult.clearedState.allFiles,
        tags: errorResult.clearedState.tags,
        nameSuggestions: errorResult.clearedState.nameSuggestions,
        miniWaveforms: errorResult.clearedState.miniWaveforms,
        contentIndex: errorResult.clearedState.contentIndex,
        libraryLoadState: errorResult.libraryLoadState,
      }));
      resetPlayerState(makeInitialPlayerState());
      console.error("素材库加载失败", err);
    }
  }, [applySnapshot, makeInitialPlayerState, resetPlayerState]);

  const handleAddLibrary = useCallback(async () => {
    if (!newLibName.trim()) {
      alert("请输入素材库名称");
      return false;
    }
    const path = await selectFolder();
    if (!path) return false;
    try {
      await addLibrary(newLibName, path, newLibType);
      const settings = await loadSettings();
      const nextState = applyLibraryMutationResult(
        buildLibraryControllerState({
          libraries: state.libraries,
          activeLibrary: state.activeLibrary,
          libraryLoadState: state.libraryLoadState,
        }),
        createLibrarySelectionResult(settings, path)
      );
      setState((prev) => ({
        ...prev,
        libraries: nextState.libraries,
        activeLibrary: nextState.activeLibrary,
        libraryLoadState: nextState.libraryLoadState,
      }));
      setNewLibName("");
      await selectLibrary(path);
      return true;
    } catch (e) {
      alert("添加素材库失败: " + e);
      return false;
    }
  }, [newLibName, newLibType, selectLibrary, state.activeLibrary, state.libraries, state.libraryLoadState]);

  const handleRemoveLibrary = useCallback(async (path: string) => {
    await removeLibrary(path);
    libraryCacheRef.current.delete(path);
    const settings = await loadSettings();
    const nextState = applyLibraryMutationResult(
      buildLibraryControllerState({
        libraries: state.libraries,
        activeLibrary: state.activeLibrary,
        libraryLoadState: state.libraryLoadState,
      }),
      createLibrarySelectionResult(settings)
    );
    setState((prev) => ({
      ...prev,
      libraries: nextState.libraries,
    }));
    if (state.activeLibrary === path) {
      if (nextState.activeLibrary) {
        setState((prev) => ({
          ...prev,
          activeLibrary: nextState.activeLibrary,
          libraryLoadState: nextState.libraryLoadState,
        }));
        await selectLibrary(nextState.activeLibrary);
      } else {
        const emptyState = buildEmptyLibrarySelection();
        setState((prev) => ({
          ...prev,
          activeLibrary: emptyState.activeLibrary,
          libraryLoadState: emptyState.libraryLoadState,
        }));
        clearLibraryView();
      }
      return;
    }

    setState((prev) => ({
      ...prev,
      activeLibrary: nextState.activeLibrary,
      libraryLoadState: nextState.libraryLoadState,
    }));
  }, [clearLibraryView, selectLibrary, state.activeLibrary, state.libraries, state.libraryLoadState]);

  const toggleFolder = useCallback((path: string) => {
    setState((prev) => {
      const next = new Set(prev.expandedFolders);
      next.has(path) ? next.delete(path) : next.add(path);
      return {
        ...prev,
        expandedFolders: next,
      };
    });
  }, []);

  useEffect(() => {
    Promise.all([loadSettings(), getSyncStatus().catch(() => null)]).then(([settings, sync]) => {
      const bootstrap = buildBootstrapResult(settings, sync);
      const nextState = buildLibraryControllerState(bootstrap);
      setState((prev) => ({
        ...prev,
        libraries: nextState.libraries,
        syncStatus: bootstrap.syncStatus,
        activeLibrary: nextState.activeLibrary,
        libraryLoadState: nextState.libraryLoadState,
      }));
      if (nextState.libraries.length === 0) {
        clearLibraryView();
      }
    });
  }, [clearLibraryView]);

  return {
    ...state,
    newLibName,
    newLibType,
    setNewLibName,
    setNewLibType,
    setSelectedFolderPath: (value: string | null) => setState((prev) => ({ ...prev, selectedFolderPath: value })),
    setMiniWaveforms: (updater: MiniWaveformMap | ((prev: MiniWaveformMap) => MiniWaveformMap)) => {
      setState((prev) => ({
        ...prev,
        miniWaveforms: typeof updater === "function" ? updater(prev.miniWaveforms) : updater,
      }));
    },

    selectLibrary,
    handleAddLibrary,
    handleRemoveLibrary,
    toggleFolder,
    clearLibraryView,
    applySnapshot,
    cacheSnapshot: (libraryPath: string, snapshot: Awaited<ReturnType<typeof buildLibrarySnapshot>>) => {
      libraryCacheRef.current.set(libraryPath, snapshot);
    },
    refreshActiveLibrarySnapshot,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";
import { getAudioSource, getWaveformPeaks } from "@/lib/api";
import { computeVolumeForAudio } from "@/lib/player-actions";
import {
  createInitialPlayerState,
  setPlaybackMuted,
  setPlaybackTime,
  setPlaybackVolume,
  type PlayerState,
} from "@/lib/player-state";
import {
  createWaveformJobGuard,
  resolveWaveformLoad,
} from "@/lib/app-effects";
import {
  buildLoadingPlayerState,
  buildNextPlayerSelection,
  buildPlaybackToggleResult,
  buildSeekState,
  buildWaveformErrorState,
  buildWaveformReadyState,
} from "@/lib/use-player-controller";
import { createAudioElementBindings } from "@/lib/use-player-events";

export function usePlayerDomain() {
  const [playerState, setPlayerState] = useState<PlayerState>(createInitialPlayerState);
  const audioRef = useRef<HTMLAudioElement>(null);
  const progressRef = useRef<HTMLDivElement>(null);
  const playheadRafRef = useRef<number | null>(null);
  const waveformJobIdRef = useRef(0);

  const currentFile = playerState.currentFile;
  const isPlaying = playerState.isPlaying;
  const isLoading = playerState.isLoading;
  const currentTime = playerState.currentTime;
  const duration = playerState.duration;
  const volume = playerState.volume;
  const isMuted = playerState.isMuted;

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = computeVolumeForAudio(volume, isMuted);
    }
  }, [volume, isMuted]);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    return createAudioElementBindings({
      audio,
      requestAnimationFrameImpl: requestAnimationFrame,
      cancelAnimationFrameImpl: cancelAnimationFrame,
      setPlayerState,
      playheadRafRef,
    });
  }, []);

  useEffect(() => {
    if (!currentFile) return;
    setPlayerState((prev) => buildLoadingPlayerState(prev));

    const jobId = ++waveformJobIdRef.current;
    const isCurrentJob = createWaveformJobGuard(waveformJobIdRef);

    void resolveWaveformLoad({
      currentFilePath: currentFile.path,
      getAudioSource,
      getWaveformPeaks,
      isCurrentJob,
      jobId,
      setAudioSource: async (sourcePath: string) => {
        if (!audioRef.current) return;
        audioRef.current.src = sourcePath;
        audioRef.current.load();
        await audioRef.current.play().catch((err) => {
          if (!isCurrentJob(jobId)) return;
          console.log("Auto play failed:", err);
        });
      },
      onReady: (waveformDuration: number) => {
        setPlayerState((prev) => buildWaveformReadyState(prev, waveformDuration));
      },
      onError: (err: unknown) => {
        console.error("资源加载失败", err);
        setPlayerState((prev) => buildWaveformErrorState(prev));
      },
    });
  }, [currentFile]);

  const resetPlayerState = useCallback((nextState: PlayerState = createInitialPlayerState()) => {
    setPlayerState(nextState);
  }, []);

  const clearAudioElement = useCallback(() => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.removeAttribute("src");
      audioRef.current.load();
    }
  }, []);

  const seekToPercent = useCallback((percent: number) => {
    if (!audioRef.current || !duration) return;
    const nextState = buildSeekState(duration, percent);
    audioRef.current.currentTime = nextState.currentTime;
    setPlayerState((prev) => setPlaybackTime(prev, nextState.currentTime));
  }, [duration]);

  const handleProgressClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    if (!progressRef.current) return;
    const rect = progressRef.current.getBoundingClientRect();
    seekToPercent((e.clientX - rect.left) / rect.width);
  }, [seekToPercent]);

  const selectFile = useCallback((name: string, path: string) => {
    const nextSelection = buildNextPlayerSelection(playerState, { name, path });
    setPlayerState(nextSelection.playerState);
    return nextSelection;
  }, [playerState]);

  const togglePlay = useCallback(() => {
    if (!audioRef.current) return;
    const nextAction = buildPlaybackToggleResult(isPlaying);
    if (nextAction.shouldPause) {
      audioRef.current.pause();
      return;
    }
    if (nextAction.shouldPlay) {
      audioRef.current.play().catch((err) => console.error("播放失败", err));
    }
  }, [isPlaying]);

  const toggleMute = useCallback(() => {
    setPlayerState((prev) => setPlaybackMuted(prev, !prev.isMuted));
  }, []);

  const setVolume = useCallback((nextVolume: number) => {
    setPlayerState((prev) => setPlaybackVolume(prev, nextVolume));
  }, []);

  const formatTime = useCallback((seconds: number) => {
    return isNaN(seconds)
      ? "00:00"
      : `${Math.floor(seconds / 60).toString().padStart(2, "0")}:${Math.floor(seconds % 60).toString().padStart(2, "0")}`;
  }, []);

  return {
    playerState,
    currentFile,
    isPlaying,
    isLoading,
    currentTime,
    duration,
    volume,
    isMuted,
    audioRef,
    progressRef,
    setPlayerState,
    resetPlayerState,
    clearAudioElement,
    selectFile,
    togglePlay,
    toggleMute,
    setVolume,
    seekToPercent,
    handleProgressClick,
    formatTime,
  };
}

import { useCallback, useMemo, useState } from "react";
import { addTag, buildLibrarySnapshot, removeTag } from "@/lib/api";
import {
  applyTagEditorReset,
  buildResolvedTagPayload,
  buildSuggestionAdoptionPlan,
  buildTagFilterToggle,
  resolveCurrentContentId,
  resolveSuggestionForFile,
  resolveTagRemovalContentId,
} from "@/lib/use-tag-controller";
import { buildCurrentFileMeta } from "@/lib/use-tag-controller";
import type {
  ContentIndexFile,
  FileMeta,
  MiniWaveformMap,
  NameTagSuggestion,
  TagEntry,
} from "@/lib/types";

export function useTagDomain(options: {
  activeLibrary: string;
  currentFile: { name: string; path: string } | null;
  allFiles: FileMeta[];
  tags: Record<string, TagEntry[]>;
  nameSuggestions: Record<string, NameTagSuggestion>;
  contentIndex: ContentIndexFile | null;
  miniWaveforms: MiniWaveformMap;
  applySnapshot: (snapshot: Awaited<ReturnType<typeof buildLibrarySnapshot>>) => void;
  cacheSnapshot: (libraryPath: string, snapshot: Awaited<ReturnType<typeof buildLibrarySnapshot>>) => void;
}) {
  const {
    activeLibrary,
    currentFile,
    allFiles,
    tags,
    nameSuggestions,
    contentIndex,
    miniWaveforms,
    applySnapshot,
    cacheSnapshot,
  } = options;

  const [tagFilters, setTagFilters] = useState<Set<string>>(new Set());
  const [showTagEditor, setShowTagEditor] = useState(false);
  const [newTagValue, setNewTagValue] = useState("");
  const [selectedTagGroup, setSelectedTagGroup] = useState("mood");

  const currentMeta = useMemo(() => buildCurrentFileMeta(allFiles, currentFile?.path ?? null), [allFiles, currentFile?.path]);

  const refreshSnapshot = useCallback(async () => {
    const snapshot = await buildLibrarySnapshot(activeLibrary);
    cacheSnapshot(activeLibrary, snapshot);
    applySnapshot(snapshot);
  }, [activeLibrary, applySnapshot, cacheSnapshot]);

  const handleAddTag = useCallback(async (groupOverride?: string, valueOverride?: string) => {
    if (!currentFile) return;
    const contentId = resolveCurrentContentId(allFiles, currentFile.path);
    if (!contentId) return;

    const payload = buildResolvedTagPayload(groupOverride, valueOverride, selectedTagGroup, newTagValue);
    if (!payload.value) return;

    await addTag(contentId, payload.group, payload.value, "user");
    await refreshSnapshot();
    setNewTagValue(applyTagEditorReset().newTagValue);
  }, [allFiles, currentFile, newTagValue, refreshSnapshot, selectedTagGroup]);

  const handleRemoveTag = useCallback(async (tag: TagEntry) => {
    if (!currentFile || !tag.group) return;
    const contentId = resolveTagRemovalContentId(allFiles, currentFile.path);
    if (!contentId) return;

    await removeTag(contentId, tag.group, tag.value);
    await refreshSnapshot();
  }, [allFiles, currentFile, refreshSnapshot]);

  const handleAdoptSuggestion = useCallback(async () => {
    if (!currentFile) return;
    const suggestion = resolveSuggestionForFile(nameSuggestions, currentFile.path);
    if (!suggestion) return;

    const contentId = resolveCurrentContentId(allFiles, currentFile.path) ?? "";
    for (const tag of buildSuggestionAdoptionPlan(suggestion)) {
      await addTag(contentId, tag.group, tag.value, "name-hint");
    }

    await refreshSnapshot();
  }, [allFiles, currentFile, nameSuggestions, refreshSnapshot]);

  const toggleTagFilter = useCallback((tag: string) => {
    setTagFilters((prev) => buildTagFilterToggle(prev, tag));
  }, []);

  return {
    tagFilters,
    showTagEditor,
    newTagValue,
    selectedTagGroup,
    currentMeta,
    setTagFilters,

    setShowTagEditor,
    setNewTagValue,
    setSelectedTagGroup,
    toggleTagFilter,
    handleAddTag,
    handleRemoveTag,
    handleAdoptSuggestion,
  };
}

import { resolveContentIdForFile } from "@/lib/tag-actions";
import type { FileMeta, NameTagSuggestion, TagEntry } from "@/lib/types";



export function buildResolvedTagPayload(
  groupOverride: string | undefined,
  valueOverride: string | undefined,
  selectedTagGroup: string,
  newTagValue: string
) {
  return {
    group: groupOverride ?? selectedTagGroup,
    value: (valueOverride ?? newTagValue).trim(),
  };
}

export function buildSuggestionAdoptionPlan(suggestion: { tags: { group: string; value: string }[] }) {
  return [...suggestion.tags];
}

export function resolveCurrentContentId(files: FileMeta[], filePath: string | null) {
  return resolveContentIdForFile(files, filePath);
}

export function resolveTagRemovalContentId(files: FileMeta[], filePath: string | null) {
  return resolveContentIdForFile(files, filePath);
}

export function resolveSuggestionForFile(
  suggestions: Record<string, NameTagSuggestion>,
  filePath: string | null
) {
  if (!filePath) {
    return null;
  }
  return suggestions[filePath] ?? null;
}



export function applyTagEditorReset() {
  return {
    newTagValue: "",
  };
}

export function buildCurrentFileMeta(files: FileMeta[], filePath: string | null) {
  if (!filePath) {
    return undefined;
  }
  return files.find((file) => file.path === filePath);
}

export function buildTagFilterToggle(current: Set<string>, tag: string) {
  const next = new Set(current);
  next.has(tag) ? next.delete(tag) : next.add(tag);
  return next;
}

