import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const accessMock = vi.fn(async () => undefined);
const spawnMock = vi.fn(() => {
  throw new Error("spawn should not be called when cache is valid");
});

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return {
    ...actual,
    spawn: spawnMock,
  };
});


type FfmpegModule = typeof import("../../electron/ffmpeg.js");

describe("ffmpeg waveform cache", () => {
  let tempRoot: string;
  let appDataDir: string;

  beforeEach(async () => {
    tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "soundbox-ffmpeg-cache-"));
    appDataDir = path.join(tempRoot, "appdata");
    accessMock.mockClear();
    spawnMock.mockClear();
  });

  afterEach(async () => {
    await fs.rm(tempRoot, { recursive: true, force: true });
    vi.restoreAllMocks();
    vi.resetModules();
  });

  it("returns cached waveform without spawning ffmpeg when cache is valid", async () => {
    const contentId = "cid:test-audio";
    const sanitized = contentId.replaceAll(":", "_");
    const cachePath = path.join(appDataDir, "Soundbox", "waveform-db", sanitized.slice(7, 9) || "00", `${sanitized}.json`);

    await fs.mkdir(path.dirname(cachePath), { recursive: true });
    await fs.writeFile(
      cachePath,
      JSON.stringify({
        version: 8,
        algorithm: "ffmpeg-f32le-peaks-v2",
        duration: 12.5,
        peaks: [0.2, 0.6, 0.4],
      }),
      "utf-8"
    );

    const module = (await import("../../electron/ffmpeg.js")) as FfmpegModule;
    const waveform = await module.getWaveformPeaks(
      (name) => {
        expect(name).toBe("appData");
        return appDataDir;
      },
      async () => contentId,
      path.join(tempRoot, "audio.wav")
    );

    expect(waveform).toEqual({ duration: 12.5, peaks: [0.2, 0.6, 0.4] });
    expect(spawnMock).not.toHaveBeenCalled();
  });

  it("deletes invalid cache file and regenerates waveform cache", async () => {
    const contentId = "cid:broken-audio";
    const sanitized = contentId.replaceAll(":", "_");
    const cachePath = path.join(appDataDir, "Soundbox", "waveform-db", sanitized.slice(7, 9) || "00", `${sanitized}.json`);
    await fs.mkdir(path.dirname(cachePath), { recursive: true });
    await fs.writeFile(cachePath, "{invalid json", "utf-8");

    const audioPath = path.join(tempRoot, "audio.wav");
    await fs.writeFile(audioPath, "seed-audio");

    const fakePcm = Buffer.alloc(16);

    const listeners: Record<string, ((arg?: unknown) => void)[]> = {};
    spawnMock.mockImplementation(() => ({
      stdout: { on: (event: string, handler: (chunk: Buffer) => void) => { listeners[`stdout:${event}`] = [...(listeners[`stdout:${event}`] ?? []), handler]; } },
      stderr: { on: (event: string, handler: (chunk: Buffer) => void) => { listeners[`stderr:${event}`] = [...(listeners[`stderr:${event}`] ?? []), handler]; } },
      on: (event: string, handler: (arg?: unknown) => void) => {
        listeners[event] = [...(listeners[event] ?? []), handler];
        if (event === "close") {
          queueMicrotask(() => {
            for (const stdoutHandler of listeners["stdout:data"] ?? []) {
              stdoutHandler(fakePcm);
            }
            handler(0);
          });
        }
      },
    }));

    const accessSpy = vi.spyOn(fs, "access").mockImplementation(accessMock);

    const module = (await import("../../electron/ffmpeg.js")) as FfmpegModule;
    const waveform = await module.getWaveformPeaks(
      () => appDataDir,
      async () => contentId,
      audioPath
    );

    expect(waveform.peaks.length).toBeGreaterThan(0);
    await expect(fs.readFile(cachePath, "utf-8")).resolves.toContain("ffmpeg-f32le-peaks-v2");
    accessSpy.mockRestore();



  });
});

import { describe, expect, it, vi } from "vitest";
import { createAudioElementBindings } from "@/lib/use-player-events";
import { createInitialPlayerState } from "@/lib/player-state";

describe("use-player-events", () => {
  it("binds and unbinds audio events", () => {
    const addEventListener = vi.fn();
    const removeEventListener = vi.fn();
    const audio = {
      currentTime: 0,
      duration: 12,
      paused: true,
      ended: false,
      addEventListener,
      removeEventListener,
    } as unknown as HTMLAudioElement;

    const cleanup = createAudioElementBindings({
      audio,
      requestAnimationFrameImpl: vi.fn((cb) => {
        cb(0);
        return 1;
      }) as unknown as typeof requestAnimationFrame,
      cancelAnimationFrameImpl: vi.fn(),
      setPlayerState: vi.fn(),
      playheadRafRef: { current: null },
    });

    expect(addEventListener).toHaveBeenCalledTimes(6);
    cleanup();
    expect(removeEventListener).toHaveBeenCalledTimes(6);
  });

  it("updates state through handlers without throwing", () => {
    const handlers = new Map<string, EventListener>();
    const audio = {
      currentTime: 5,
      duration: 20,
      paused: false,
      ended: false,
      addEventListener: vi.fn((name: string, handler: EventListener) => handlers.set(name, handler)),
      removeEventListener: vi.fn(),
    } as unknown as HTMLAudioElement;

    const updates: Array<ReturnType<typeof createInitialPlayerState>> = [];
    createAudioElementBindings({
      audio,
      requestAnimationFrameImpl: vi.fn(() => 1) as unknown as typeof requestAnimationFrame,
      cancelAnimationFrameImpl: vi.fn(),
      setPlayerState: (updater) => updates.push(updater(createInitialPlayerState())),
      playheadRafRef: { current: null },
    });

    handlers.get("loadedmetadata")?.(new Event("loadedmetadata"));
    handlers.get("play")?.(new Event("play"));
    handlers.get("pause")?.(new Event("pause"));
    handlers.get("ended")?.(new Event("ended"));
    handlers.get("error")?.(new Event("error"));

    expect(updates.length).toBeGreaterThan(0);
  });
});
